/* The design system's rules for the macOS app (cmux-tui/crates/cmux-design-core, src/ffi.rs):
 * one JSON op call per decision; the app draws, Rust decides. */

#ifndef CMUX_DESIGN_H
#define CMUX_DESIGN_H

/* Generated by cbindgen (cmux-tui/crates/cmux-design-core/cbindgen.toml); do not edit.
 * Regenerate: CMUX_APP_FFI_HEADER_BLESS=1 cargo test --test design_header (cmux-app-ffi) */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 Bumped on any change to a type or a function (a new op is not one).
 */
#define CMUX_DESIGN_ABI_VERSION 1

/*
 The op ran; `*out` holds its reply.
 */
#define CMUX_DESIGN_OK 0

/*
 A null pointer where one is required.
 */
#define CMUX_DESIGN_ERR_NULL -1

/*
 Not UTF-8, or not the JSON the op takes.
 */
#define CMUX_DESIGN_ERR_INVALID -2

/*
 No such op.
 */
#define CMUX_DESIGN_ERR_UNKNOWN_OP -3

/*
 A panic inside, caught.
 */
#define CMUX_DESIGN_ERR_PANIC -4

/*
 A reply buffer owned by the caller (JSON, UTF-8). `ptr` is null when `len` is 0.
 */
typedef struct {
    uint8_t *ptr;
    size_t len;
} CmuxDesignBytes;

/*
 `CMUX_DESIGN_ABI_VERSION`.
 */
uint32_t cmux_design_abi_version(void);

/*
 Runs one JSON op: `op` (NUL-terminated, such as `toast.plan`) on `request` (a JSON object,
 UTF-8; empty reads as `{}`); `*out` gets the reply's JSON, which the caller frees with
 `cmux_design_bytes_free`.

 # Safety

 `op` is a NUL-terminated string; `request_ptr` with `request_len` is readable; `out` is
 writable.
 */
int32_t cmux_design_call(const char *op, const uint8_t *request_ptr, size_t request_len, CmuxDesignBytes *out);

/*
 Frees a reply buffer. A null `ptr` is ignored.

 # Safety

 `bytes` came from `cmux_design_call` and is freed once.
 */
void cmux_design_bytes_free(CmuxDesignBytes bytes);

#endif  /* CMUX_DESIGN_H */
